effect.shader:
#define PI 3.14159265359
vec2 hash22(vec2 p) {
vec3 p3 = fract(vec3(p.xyx) * vec3(0.1031, 0.1030, 0.0973));
p3 += dot(p3, p3.yzx + 33.33);
return fract((p3.xx + p3.yz) * p3.zy);
}
mat2 rot(float a) {
float s = sin(a);
float c = cos(a);
return mat2(c, -s, s, c);
}
void main() {
vec2 uv = acScreenNorm;
float aspect = acScreenSize.x / max(acScreenSize.y, 1.0);
vec2 st = (uv - 0.5) * vec2(aspect, 1.0);
st *= rot(facetAngle * 0.0174532925);
vec2 gv = st * facetDensity;
vec2 id = floor(gv);
vec2 fv = fract(gv);
float minDist = 100.0;
vec2 minCell = vec2(0.0);
vec2 minDiff = vec2(0.0);
for(int y = -1; y <= 1; y++) {
for(int x = -1; x <= 1; x++) {
vec2 neighbor = vec2(float(x), float(y));
vec2 pt = hash22(id + neighbor);
vec2 diff = neighbor + pt - fv;
float dist = length(diff);
if (dist < minDist) {
minDist = dist;
minCell = id + neighbor;
minDiff = diff;
}
}
}
float minEdge = 100.0;
for(int y = -1; y <= 1; y++) {
for(int x = -1; x <= 1; x++) {
vec2 neighbor = vec2(float(x), float(y));
vec2 pt = hash22(id + neighbor);
vec2 diff = neighbor + pt - fv;
if (dot(minDiff - diff, minDiff - diff) > 0.00001) {
float d = dot(0.5 * (minDiff + diff), normalize(diff - minDiff));
minEdge = min(minEdge, d);
}
}
}
vec2 cellRand = hash22(minCell) - 0.5;
vec2 facetTilt = cellRand * 2.0;
float edgeNorm = smoothstep(0.0, 0.15, minEdge);
vec2 facetNormal = normalize(minDiff + facetTilt * 0.5) * (1.0 - edgeNorm * bevelSharpness);
vec2 dispVec = (facetNormal * iorStrength) * vec2(1.0 / aspect, 1.0);
vec2 dispChroma = (facetNormal * dispersion) * vec2(1.0 / aspect, 1.0);
vec4 colR = texture2DCv(inputImg.texture, clamp(uv + dispVec + dispChroma, 0.0, 1.0));
vec4 colG = texture2DCv(inputImg.texture, clamp(uv + dispVec, 0.0, 1.0));
vec4 colB = texture2DCv(inputImg.texture, clamp(uv + dispVec - dispChroma, 0.0, 1.0));
vec3 refracted = vec3(colR.r, colG.g, colB.b);
float causticLine = smoothstep(0.04, 0.0, minEdge) * 1.5;
float shimmer = sin(acTime * shimmerSpeed * 3.0 + dot(minCell, vec2(12.7, 31.1))) * 0.5 + 0.5;
shimmer = pow(shimmer, 4.0);
vec3 causticGlow = sparkleColor.rgb * (causticLine + shimmer * 0.8) * caustics * sparkleColor.a;
refracted += causticGlow;
vec4 original = texture2DCv(inputImg.texture, uv);
vec4 finalColor = vec4(clamp(refracted, 0.0, 1.0), colG.a);
gl_FragColor = mix(original, finalColor, alpha);
}
